  R.panel = name; R.panelArg = arg; R.panelNext = null; R.panelOnClose = opts && opts.onClose;
  R.keys = {}; R.mouseDown = false; if (R.touchReset) R.touchReset();
  $('panel').className = 'on p_' + name; R.panelOpenT = performance.now(); renderPanel();
